#!/data/data/com.termux/files/usr/bin/bash
set -u
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
ENGINE="$ROOT/core/engine.sh"
TOOL="${1:-}"; shift || true
[ -n "$TOOL" ] || { echo 'Usage: zyvorax <tool> [args...]'; exit 1; }
case "$TOOL" in
system-info) exec bash "$ENGINE" system_info "$@";; cpu-info) exec bash "$ENGINE" cpu_info "$@";; memory-info) exec bash "$ENGINE" memory_info "$@";; storage-info|disk-free) exec bash "$ENGINE" storage_info "$@";; process-list) exec bash "$ENGINE" processes "$@";; date-time) exec bash "$ENGINE" date_time "$@";; calendar) exec bash "$ENGINE" calendar "$@";; whoami) exec bash "$ENGINE" whoami "$@";; hostname) exec bash "$ENGINE" hostname "$@";; os-release) exec bash "$ENGINE" os_release "$@";; network-info|network-status) exec bash "$ENGINE" network_info "$@";; routes) exec bash "$ENGINE" routes "$@";; dns-info) exec bash "$ENGINE" dns_info "$@";; ping) exec bash "$ENGINE" ping_localhost "$@";; ports-list) exec bash "$ENGINE" ports_list "$@";; public-ip) exec bash "$ENGINE" public_ip "$@";; resolve-domain) exec bash "$ENGINE" resolve_domain "$@";; url-status) exec bash "$ENGINE" url_status "$@";; http-headers) exec bash "$ENGINE" http_headers "$@";; tcp-check) exec bash "$ENGINE" tcp_check "$@";;
file-find) exec bash "$ENGINE" file_find "$@";; large-files) exec bash "$ENGINE" large_files "$@";; file-count) exec bash "$ENGINE" file_count "$@";; file-preview) exec bash "$ENGINE" file_preview "$@";; file-tail) exec bash "$ENGINE" file_tail "$@";; file-type) exec bash "$ENGINE" file_type "$@";; checksum) exec bash "$ENGINE" checksum "$@";; text-search) exec bash "$ENGINE" text_search "$@";; archive-list) exec bash "$ENGINE" archive_list "$@";; archive-create) exec bash "$ENGINE" archive_create "$@";; archive-extract) exec bash "$ENGINE" archive_extract "$@";;
bash-check) exec bash "$ENGINE" bash_check "$@";; python-check) exec bash "$ENGINE" python_check "$@";; node-check) exec bash "$ENGINE" node_check "$@";; json-check) exec bash "$ENGINE" json_check "$@";; json-pretty) exec bash "$ENGINE" json_pretty "$@";; code-stats) exec bash "$ENGINE" code_stats "$@";; which) exec bash "$ENGINE" command_exists "$@";; git-status) exec bash "$ENGINE" git_status "$@";; git-log) exec bash "$ENGINE" git_log "$@";; git-diff) exec bash "$ENGINE" git_diff "$@";; git-branch) exec bash "$ENGINE" git_branch "$@";; git-remotes) exec bash "$ENGINE" git_remotes "$@";;
termux-info) exec bash "$ENGINE" termux_info "$@";; android-version) exec bash "$ENGINE" android_version "$@";; device-model) exec bash "$ENGINE" device_model "$@";; battery-status) exec bash "$ENGINE" battery_info "$@";; clipboard-get) exec bash "$ENGINE" clipboard_get "$@";; clipboard-set) exec bash "$ENGINE" clipboard_set "$@";; notification) exec bash "$ENGINE" notification "$@";; toast) exec bash "$ENGINE" toast "$@";; vibrate) exec bash "$ENGINE" vibrate "$@";; tts) exec bash "$ENGINE" tts "$@";; torch) exec bash "$ENGINE" torch "$@";;
upper) exec bash "$ENGINE" text_upper "$@";; lower) exec bash "$ENGINE" text_lower "$@";; reverse) exec bash "$ENGINE" text_reverse "$@";; trim) exec bash "$ENGINE" text_trim "$@";; repeat) exec bash "$ENGINE" text_repeat "$@";; replace) exec bash "$ENGINE" text_replace "$@";; clean-text) exec bash "$ENGINE" text_clean "$@";; word-count) exec bash "$ENGINE" word_count "$@";; line-count) exec bash "$ENGINE" line_count "$@";; text-grep) exec bash "$ENGINE" text_grep "$@";;
json-keys) exec bash "$ENGINE" json_keys "$@";; json-get) exec bash "$ENGINE" json_get "$@";; csv-head) exec bash "$ENGINE" csv_head "$@";; sum) exec bash "$ENGINE" data_sum "$@";; average) exec bash "$ENGINE" data_average "$@";; min) exec bash "$ENGINE" data_min "$@";; max) exec bash "$ENGINE" data_max "$@";; stats) exec bash "$ENGINE" data_stats "$@";;
web-get|curl-get) exec bash "$ENGINE" web_get "$@";; web-headers|curl-head) exec bash "$ENGINE" web_headers "$@";; web-status) exec bash "$ENGINE" web_status "$@";; download) exec bash "$ENGINE" web_download "$@";; domain) exec bash "$ENGINE" web_domain "$@";; url-encode) exec bash "$ENGINE" web_encode "$@";; url-decode) exec bash "$ENGINE" web_decode "$@";; domain-ip) exec bash "$ENGINE" web_ip "$@";; redirects) exec bash "$ENGINE" web_redirects "$@";; web-time) exec bash "$ENGINE" web_time "$@";; web-size) exec bash "$ENGINE" web_size "$@";;
random) exec bash "$ENGINE" random_number "$@";; password) exec bash "$ENGINE" password_gen "$@";; uuid) exec bash "$ENGINE" uuid "$@";; calc|calculator) exec bash "$ENGINE" calculator "$@";; base64-encode) exec bash "$ENGINE" base64_encode "$@";; base64-decode) exec bash "$ENGINE" base64_decode "$@";; color-test) exec bash "$ENGINE" color_test "$@";; ascii-table) exec bash "$ENGINE" ascii_table "$@";; banner) exec bash "$ENGINE" banner "$@";; health-check) exec bash "$ENGINE" health_check "$@";;
note) mkdir -p "$HOME/.zyvorax/notes"; printf '%s\n' "${*:-}" >> "$HOME/.zyvorax/notes/notes.txt"; echo 'Note saved.';; notes) cat "$HOME/.zyvorax/notes/notes.txt" 2>/dev/null || echo 'No notes yet.';; todo) mkdir -p "$HOME/.zyvorax/todo"; printf '[ ] %s\n' "${*:-}" >> "$HOME/.zyvorax/todo/list.txt"; echo 'Todo added.';; todos) cat "$HOME/.zyvorax/todo/list.txt" 2>/dev/null || echo 'No todos yet.';; todo-done) sed -i "${1:-1}s/^\[ \]/[x]/" "$HOME/.zyvorax/todo/list.txt" 2>/dev/null || true; echo 'Todo updated.';; timer|stopwatch) seconds="${1:-300}"; echo "Timer: ${seconds}s"; sleep "$seconds"; printf '\a'; echo 'DONE.';;
*) echo "ZYVORAX: $TOOL"; echo 'Catalog entry available; this name currently uses the generic safe handler.';; esac
